@dataclass
class Paths:
    root: Path
    manifest: Path
    target: Path
    prediction: Path
    models: Path
    kernels: Path
    scheduling: Path
    qaoa: Path
    statistics: Path
    iquantum: Path
    ablations: Path
    figures: Path
    logs: Path
    circuits: Path
    sources: Path
    circuit_artifacts: Path
    helpers: Path

    @classmethod
    def create(cls, run_name: str) -> "Paths":
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        root = FINAL_ROOT / f"{stamp}_{run_name}"
        if root.exists():
            raise FileExistsError(root)

        obj = cls(
            root=root,
            manifest=root / "00_manifest",
            target=root / "01_future_target",
            prediction=root / "02_prediction_hcqkl",
            models=root / "03_models",
            kernels=root / "04_kernel_artifacts",
            scheduling=root / "05_capacity_scheduling",
            qaoa=root / "06_compact_qaoa",
            statistics=root / "07_statistics",
            iquantum=root / "08_iquantum_calibrated_v4",
            ablations=root / "09_ablations",
            figures=root / "10_figures",
            logs=root / "11_logs",
            circuits=root / "12_updated_quantum_circuit_figures",
            sources=root / "13_source_snapshots",
            circuit_artifacts=root / "14_quantum_circuit_artifacts",
            helpers=root / "_embedded_helpers",
        )

        for p in obj.__dict__.values():
            if isinstance(p, Path):
                p.mkdir(parents=True, exist_ok=True)
        return obj

    @classmethod
    def from_existing(cls, root: Path) -> "Paths":
        root = Path(root).resolve()
        obj = cls(
            root=root,
            manifest=root / "00_manifest",
            target=root / "01_future_target",
            prediction=root / "02_prediction_hcqkl",
            models=root / "03_models",
            kernels=root / "04_kernel_artifacts",
            scheduling=root / "05_capacity_scheduling",
            qaoa=root / "06_compact_qaoa",
            statistics=root / "07_statistics",
            iquantum=root / "08_iquantum_calibrated_v4",
            ablations=root / "09_ablations",
            figures=root / "10_figures",
            logs=root / "11_logs",
            circuits=root / "12_updated_quantum_circuit_figures",
            sources=root / "13_source_snapshots",
            circuit_artifacts=root / "14_quantum_circuit_artifacts",
            helpers=root / "_embedded_helpers",
        )
        for p in obj.__dict__.values():
            if isinstance(p, Path):
                p.mkdir(parents=True, exist_ok=True)
        return obj


