def save_json(obj: Any, path: Path) -> None:
    def conv(x: Any) -> Any:
        if isinstance(x, Path):
            return str(x)
        if isinstance(x, (np.integer,)):
            return int(x)
        if isinstance(x, (np.floating,)):
            return float(x)
        if isinstance(x, np.ndarray):
            return x.tolist()
        if isinstance(x, (set, tuple, list)):
            return [conv(v) for v in x]
        if isinstance(x, dict):
            return {str(k): conv(v) for k, v in x.items()}
        return x

    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(conv(obj), indent=2, ensure_ascii=False),
        encoding="utf-8",
    )


def file_sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def numeric(df: pd.DataFrame, cols: Sequence[str]) -> pd.DataFrame:
    out = df.loc[:, cols].copy()
    for c in cols:
        out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def natural_subsample(df: pd.DataFrame, max_n: int) -> pd.DataFrame:
    if len(df) <= max_n:
        return df.copy().reset_index(drop=True)
    ids = np.linspace(0, len(df) - 1, max_n, dtype=int)
    return df.iloc[ids].copy().reset_index(drop=True)


def class_enriched_train(
    df: pd.DataFrame,
    max_n: int,
    positive_max: int,
) -> pd.DataFrame:
    pos = df[df["future_sla_event"] == 1]
    neg = df[df["future_sla_event"] == 0]

    n_pos = min(len(pos), positive_max, max_n // 2)
    n_neg = min(len(neg), max_n - n_pos)

    if n_pos == 0 or n_neg == 0:
        raise RuntimeError(
            "Kernel training cannot proceed because one class is absent."
        )

    return (
        pd.concat(
            [
                natural_subsample(pos, n_pos),
                natural_subsample(neg, n_neg),
            ],
            axis=0,
        )
        .sort_values(TIME_COLUMN, kind="mergesort")
        .reset_index(drop=True)
    )


def temporal_split(df: pd.DataFrame):
    d = df.sort_values(TIME_COLUMN, kind="mergesort").reset_index(drop=True)
    n = len(d)
    a = int(n * TRAIN_FRACTION)
    b = int(n * (TRAIN_FRACTION + VALIDATION_FRACTION))
    return (
        d.iloc[:a].copy(),
        d.iloc[a:b].copy(),
        d.iloc[b:].copy(),
    )


def ece(y: np.ndarray, p: np.ndarray, bins: int = 10) -> float:
    y = np.asarray(y, int)
    p = np.clip(np.asarray(p, float), 0.0, 1.0)
    edges = np.linspace(0.0, 1.0, bins + 1)
    ans = 0.0
    for i in range(bins):
        if i == bins - 1:
            m = (p >= edges[i]) & (p <= edges[i + 1])
        else:
            m = (p >= edges[i]) & (p < edges[i + 1])
        if m.any():
            ans += m.mean() * abs(float(y[m].mean()) - float(p[m].mean()))
    return float(ans)


def choose_threshold(y: np.ndarray, p: np.ndarray) -> float:
    y = np.asarray(y, int)
    p = np.asarray(p, float)

    if len(np.unique(y)) < 2:
        return 0.5

    candidates = np.unique(
        np.quantile(p, np.linspace(0.01, 0.99, 199))
    )
    best_t = 0.5
    best_f1 = -np.inf

    for t in candidates:
        score = f1_score(
            y,
            (p >= t).astype(int),
            zero_division=0,
        )
        if score > best_f1:
            best_t = float(t)
            best_f1 = float(score)

    return best_t


def classification_metrics(
    y: np.ndarray,
    p: np.ndarray,
    threshold: float,
) -> dict[str, Any]:
    y = np.asarray(y, int)
    p = np.clip(np.asarray(p, float), 1e-8, 1 - 1e-8)
    pred = (p >= threshold).astype(int)

    tn, fp, fn, tp = confusion_matrix(
        y, pred, labels=[0, 1]
    ).ravel()

    return {
        "n": int(len(y)),
        "positives": int(y.sum()),
        "prevalence": float(y.mean()),
        "threshold": float(threshold),
        "accuracy": float(accuracy_score(y, pred)),
        "balanced_accuracy": float(
            balanced_accuracy_score(y, pred)
        ),
        "precision": float(
            precision_score(y, pred, zero_division=0)
        ),
        "recall": float(
            recall_score(y, pred, zero_division=0)
        ),
        "specificity": (
            float(tn / (tn + fp)) if (tn + fp) else np.nan
        ),
        "f1": float(
            f1_score(y, pred, zero_division=0)
        ),
        "mcc": float(matthews_corrcoef(y, pred)),
        "roc_auc": (
            float(roc_auc_score(y, p))
            if len(np.unique(y)) > 1 else np.nan
        ),
        "pr_auc": (
            float(average_precision_score(y, p))
            if len(np.unique(y)) > 1 else np.nan
        ),
        "brier": float(brier_score_loss(y, p)),
        "log_loss": float(log_loss(y, p, labels=[0, 1])),
        "ece10": float(ece(y, p, 10)),
        "tp": int(tp),
        "tn": int(tn),
        "fp": int(fp),
        "fn": int(fn),
    }


def bootstrap_ci(
    values: Sequence[float],
    resamples: int,
    seed: int,
) -> tuple[float, float]:
    x = np.asarray(values, dtype=float)
    x = x[np.isfinite(x)]
    if len(x) == 0:
        return np.nan, np.nan

    rng = np.random.default_rng(seed)
    stats = np.empty(resamples, dtype=float)

    for b in range(resamples):
        s = rng.choice(x, size=len(x), replace=True)
        stats[b] = np.mean(s)

    return (
        float(np.quantile(stats, 0.025)),
        float(np.quantile(stats, 0.975)),
    )


def paired_cohens_dz(d: Sequence[float]) -> float:
    d = np.asarray(d, dtype=float)
    d = d[np.isfinite(d)]
    if len(d) < 2:
        return np.nan

    sd = np.std(d, ddof=1)
    if np.isclose(sd, 0):
        return 0.0 if np.isclose(np.mean(d), 0) else np.inf * np.sign(np.mean(d))

    return float(np.mean(d) / sd)


def holm_adjust(p_values: Sequence[float]) -> np.ndarray:
    p = np.asarray(p_values, dtype=float)
    ans = np.full(len(p), np.nan)
    valid = np.where(np.isfinite(p))[0]

    if not len(valid):
        return ans

    order = valid[np.argsort(p[valid])]
    m = len(order)
    running = 0.0

    for rank, idx in enumerate(order):
        adjusted = min(1.0, (m - rank) * p[idx])
        running = max(running, adjusted)
        ans[idx] = running

    return ans


