def decode_helper(encoded: str) -> bytes:
    return zlib.decompress(base64.b64decode(encoded.encode("ascii")))


def write_embedded_helpers(out: Paths) -> dict[str, Path]:
    helpers = {
        "compact_qaoa": (
            "30_aqua_sla_compact_qaoa_iquantum_stats.py",
            EMBEDDED_HELPER30,
        ),
        "iquantum_v4": (
            "32_aqua_sla_iquantum_risk_calibrated_v4.py",
            EMBEDDED_HELPER32,
        ),
        "circuits": (
            "33_aqua_sla_save_updated_quantum_circuits.py",
            EMBEDDED_HELPER33,
        ),
    }

    paths = {}
    manifest = []

    for key, (name, payload) in helpers.items():
        p = out.helpers / name
        p.write_bytes(decode_helper(payload))
        paths[key] = p
        manifest.append({
            "helper": key,
            "path": str(p),
            "sha256": file_sha256(p),
        })

    pd.DataFrame(manifest).to_csv(
        out.sources / "embedded_helper_manifest.csv",
        index=False,
    )

    # Also preserve the full final launcher itself.
    try:
        this = Path(__file__).resolve()
        shutil.copy2(
            this,
            out.sources / this.name,
        )
    except Exception:
        pass

    return paths


def load_module(path: Path, module_name: str):
    spec = importlib.util.spec_from_file_location(
        module_name,
        str(path),
    )
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Cannot import helper module: {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    spec.loader.exec_module(module)
    return module


