def prepare_target_frame(raw: pd.DataFrame) -> pd.DataFrame:
    required = TASK_KEYS + [TIME_COLUMN, EVENT_COLUMN]
    missing = [c for c in required if c not in raw.columns]
    if missing:
        raise ValueError(
            f"Missing target-construction columns: {missing}"
        )

    df = raw.copy()
    df["_source_row"] = np.arange(len(df), dtype=np.int64)

    df[TIME_COLUMN] = pd.to_numeric(
        df[TIME_COLUMN], errors="coerce"
    )
    df[EVENT_COLUMN] = (
        df[EVENT_COLUMN]
        .astype(str)
        .str.upper()
        .str.strip()
    )

    if END_TIME_COLUMN in df.columns:
        df[END_TIME_COLUMN] = pd.to_numeric(
            df[END_TIME_COLUMN],
            errors="coerce",
        )
    else:
        df[END_TIME_COLUMN] = np.nan

    df = df.dropna(subset=[TIME_COLUMN]).copy()

    for c in TASK_KEYS:
        df[c] = df[c].astype(str)

    return (
        df.sort_values(
            TASK_KEYS + [TIME_COLUMN, "_source_row"],
            kind="mergesort",
        )
        .reset_index(drop=True)
    )


def lifecycle_annotations(
    df: pd.DataFrame,
    clean_terminal_events: set[str],
) -> pd.DataFrame:
    n = len(df)

    next_disruption = np.full(n, np.nan)
    next_clean_terminal = np.full(n, np.nan)
    prior_disruption = np.zeros(n, dtype=bool)
    task_last_event = np.full(n, np.nan)
    task_observation_end = np.full(n, np.nan)

    groups = df.groupby(
        TASK_KEYS,
        sort=False,
    ).indices

    for _, ids0 in groups.items():
        ids = np.asarray(ids0, dtype=int)
        times = df.loc[ids, TIME_COLUMN].to_numpy(float)
        events = df.loc[ids, EVENT_COLUMN].to_numpy(str)

        last_event = float(np.nanmax(times))

        end_values = pd.to_numeric(
            df.loc[ids, END_TIME_COLUMN],
            errors="coerce",
        ).to_numpy(float)
        valid_end = end_values[np.isfinite(end_values)]

        observation_end = (
            max(last_event, float(np.nanmax(valid_end)))
            if len(valid_end)
            else last_event
        )

        task_last_event[ids] = last_event
        task_observation_end[ids] = observation_end

        nd = np.nan
        nc = np.nan

        for pos in range(len(ids) - 1, -1, -1):
            gid = ids[pos]

            next_disruption[gid] = nd
            next_clean_terminal[gid] = nc

            ev = events[pos]
            t = times[pos]

            if ev in DISRUPTIVE_EVENTS:
                nd = t

            if ev in clean_terminal_events:
                nc = t

        seen = False
        for pos in range(len(ids)):
            gid = ids[pos]
            prior_disruption[gid] = seen

            if events[pos] in DISRUPTIVE_EVENTS:
                seen = True

    out = df.copy()
    out["next_disruption_time"] = next_disruption
    out["next_clean_terminal_time"] = next_clean_terminal
    out["prior_disruption"] = prior_disruption
    out["current_disruption"] = out[EVENT_COLUMN].isin(
        DISRUPTIVE_EVENTS
    )
    out["task_last_event_time"] = task_last_event
    out["task_observation_end_time"] = task_observation_end

    return out


def build_global_only_target(
    annotated: pd.DataFrame,
    horizon: float,
):
    df = annotated.copy()
    global_end = float(df[TIME_COLUMN].max())

    delta = (
        df["next_disruption_time"]
        - df[TIME_COLUMN]
    )

    df["future_sla_event"] = (
        df["next_disruption_time"].notna()
        & (delta > 0)
        & (delta <= horizon)
    ).astype(int)

    df["right_censored_global_only"] = (
        df[TIME_COLUMN] > global_end - horizon
    )

    eligible = df[
        ~df["current_disruption"]
        & ~df["prior_disruption"]
        & ~df["right_censored_global_only"]
    ].copy()

    return eligible.reset_index(drop=True)


def build_lifecycle_target(
    annotated: pd.DataFrame,
    horizon: float,
    clean_terminal_events: set[str],
):
    df = annotated.copy()

    ti = df[TIME_COLUMN].to_numpy(float)
    nd = df["next_disruption_time"].to_numpy(float)
    nc = df["next_clean_terminal_time"].to_numpy(float)
    obs_end = df["task_observation_end_time"].to_numpy(float)

    horizon_end = ti + float(horizon)
    global_end = float(df[TIME_COLUMN].max())

    disruptive = (
        np.isfinite(nd)
        & (nd > ti)
        & (nd <= horizon_end)
    )

    clean_before_disruption = (
        np.isfinite(nc)
        & (nc > ti)
        & (nc <= horizon_end)
        & (~np.isfinite(nd) | (nc < nd))
    )

    positive = disruptive & ~clean_before_disruption

    observed_through_horizon = (
        np.isfinite(obs_end)
        & (obs_end >= horizon_end)
        & (horizon_end <= global_end)
    )

    lifecycle_censored = (
        ~positive
        & ~clean_before_disruption
        & ~observed_through_horizon
    )

    df["horizon_end_time"] = horizon_end
    df["positive_disruption_in_horizon"] = positive
    df["known_clean_negative"] = clean_before_disruption
    df["observed_through_horizon"] = observed_through_horizon
    df["right_censored_task_lifecycle"] = lifecycle_censored
    df["future_sla_event"] = positive.astype(int)

    eligible = df[
        ~df["current_disruption"]
        & ~df["prior_disruption"]
        & ~df["right_censored_task_lifecycle"]
    ].copy().reset_index(drop=True)

    meta = {
        "horizon_seconds": float(horizon),
        "decision_time": TIME_COLUMN,
        "task_keys": TASK_KEYS,
        "positive_definition": (
            "same-task FAIL/LOST/EVICT/KILL in (Ti,Ti+H] "
            "before an earlier clean terminal"
        ),
        "negative_definition": (
            "no disruptive event in horizon and either explicit clean "
            "terminal before horizon or observation through Ti+H"
        ),
        "clean_terminal_events": sorted(
            clean_terminal_events
        ),
        "censoring": (
            "task-level right censoring for insufficient follow-up"
        ),
        "source_rows": int(len(annotated)),
        "eligible_rows": int(len(eligible)),
        "positives": int(
            eligible["future_sla_event"].sum()
        ),
        "negatives": int(
            (eligible["future_sla_event"] == 0).sum()
        ),
        "prevalence": float(
            eligible["future_sla_event"].mean()
        ),
        "task_lifecycle_censored_rows": int(
            lifecycle_censored.sum()
        ),
        "known_clean_negative_rows": int(
            clean_before_disruption.sum()
        ),
        "observed_through_horizon_rows": int(
            observed_through_horizon.sum()
        ),
    }

    return eligible, meta


def target_audit(
    annotated: pd.DataFrame,
    clean_terminal_events: set[str],
    horizons: Sequence[float],
    out: Paths,
):
    rows = []
    primary = None
    primary_meta = None

    for H in horizons:
        old = build_global_only_target(
            annotated,
            H,
        )
        strict, meta = build_lifecycle_target(
            annotated,
            H,
            clean_terminal_events,
        )

        old_key = old[
            ["_source_row", "future_sla_event"]
        ].rename(
            columns={"future_sla_event": "old_label"}
        )
        strict_key = strict[
            ["_source_row", "future_sla_event"]
        ].rename(
            columns={"future_sla_event": "strict_label"}
        )

        merged = old_key.merge(
            strict_key,
            on="_source_row",
            how="outer",
            indicator=True,
        )

        common = merged[
            merged["_merge"] == "both"
        ].copy()

        changed = int(
            (
                common["old_label"].astype(int)
                != common["strict_label"].astype(int)
            ).sum()
        )

        rows.append({
            "horizon_seconds": H,
            "old_global_only_eligible": len(old),
            "strict_lifecycle_eligible": len(strict),
            "old_only_rows": int(
                (merged["_merge"] == "left_only").sum()
            ),
            "strict_only_rows": int(
                (merged["_merge"] == "right_only").sum()
            ),
            "common_rows": int(
                (merged["_merge"] == "both").sum()
            ),
            "changed_labels_on_common_rows": changed,
            "old_positives": int(
                old["future_sla_event"].sum()
            ),
            "strict_positives": int(
                strict["future_sla_event"].sum()
            ),
            "old_prevalence": float(
                old["future_sla_event"].mean()
            ),
            "strict_prevalence": float(
                strict["future_sla_event"].mean()
            ),
            "task_lifecycle_censored_rows": (
                meta["task_lifecycle_censored_rows"]
            ),
        })

        if math.isclose(H, PRIMARY_HORIZON):
            primary = strict
            primary_meta = meta

    audit = pd.DataFrame(rows)
    audit.to_csv(
        out.target / "global_vs_task_lifecycle_audit.csv",
        index=False,
    )

    if primary is None:
        primary, primary_meta = build_lifecycle_target(
            annotated,
            PRIMARY_HORIZON,
            clean_terminal_events,
        )

    return primary, primary_meta, audit


# =============================================================================
# Prediction: classical baselines
# =============================================================================

def make_baseline_models(fast: bool):
    try:
        from xgboost import XGBClassifier
    except Exception as exc:
        raise RuntimeError(
            "XGBoost is required for the final reviewer-complete run. "
            "Install it with: pip install xgboost"
        ) from exc

    return {
        "HistGradientBoosting": Pipeline([
            ("imputer", SimpleImputer(strategy="median")),
            ("scaler", RobustScaler()),
            ("clf", HistGradientBoostingClassifier(
                learning_rate=0.05,
                max_iter=250 if fast else 350,
                max_leaf_nodes=31,
                min_samples_leaf=20,
                l2_regularization=1.0,
                random_state=SEED,
            )),
        ]),
        "RandomForest": Pipeline([
            ("imputer", SimpleImputer(strategy="median")),
            ("clf", RandomForestClassifier(
                n_estimators=150 if fast else 500,
                min_samples_leaf=4,
                class_weight="balanced_subsample",
                n_jobs=-1,
                random_state=SEED,
            )),
        ]),
        "MLP": Pipeline([
            ("imputer", SimpleImputer(strategy="median")),
            ("scaler", RobustScaler()),
            ("clf", MLPClassifier(
                hidden_layer_sizes=(64, 32),
                activation="relu",
                alpha=1e-4,
                max_iter=120 if fast else 300,
                early_stopping=True,
                validation_fraction=0.15,
                random_state=SEED,
            )),
        ]),
        "XGBoost": Pipeline([
            ("imputer", SimpleImputer(strategy="median")),
            ("clf", XGBClassifier(
                n_estimators=120 if fast else 400,
                max_depth=5,
                learning_rate=0.05,
                subsample=0.85,
                colsample_bytree=0.85,
                eval_metric="logloss",
                n_jobs=-1,
                random_state=SEED,
            )),
        ]),
    }


def run_classical_baselines(
    train: pd.DataFrame,
    val: pd.DataFrame,
    test: pd.DataFrame,
    out: Paths,
    fast: bool,
):
    feats = [
        c for c in EARLY_FEATURES
        if c in train.columns
    ]

    max_train = (
        min(20_000, len(train))
        if fast
        else min(CLASSICAL_TRAIN_MAX, len(train))
    )

    tr = natural_subsample(
        train,
        max_train,
    )

    Xtr = numeric(tr, feats)
    ytr = tr["future_sla_event"].to_numpy(int)

    Xv = numeric(val, feats)
    yv = val["future_sla_event"].to_numpy(int)

    Xt = numeric(test, feats)
    yt = test["future_sla_event"].to_numpy(int)

    rows = []
    pred = pd.DataFrame({
        "_source_row": test["_source_row"].to_numpy(),
        TIME_COLUMN: test[TIME_COLUMN].to_numpy(),
        "future_sla_event": yt,
    })

    for name, model in make_baseline_models(
        fast
    ).items():
        start = time.perf_counter()

        if name == "HistGradientBoosting":
            sw = compute_sample_weight(
                "balanced",
                ytr,
            )
            model.fit(
                Xtr,
                ytr,
                clf__sample_weight=sw,
            )
        elif name == "XGBoost":
            pos = max(int(ytr.sum()), 1)
            neg = max(int((ytr == 0).sum()), 1)
            model.set_params(
                clf__scale_pos_weight=neg / pos
            )
            model.fit(Xtr, ytr)
        else:
            model.fit(Xtr, ytr)

        train_seconds = (
            time.perf_counter() - start
        )

        pv = model.predict_proba(Xv)[:, 1]
        threshold = choose_threshold(
            yv,
            pv,
        )

        infer_start = time.perf_counter()
        pt = model.predict_proba(Xt)[:, 1]
        infer_seconds = (
            time.perf_counter() - infer_start
        )

        rows.append({
            "model": name,
            "train_rows": len(tr),
            "train_seconds": train_seconds,
            "test_inference_seconds": infer_seconds,
            **classification_metrics(
                yt,
                pt,
                threshold,
            ),
        })

        pred[f"p_{name}"] = pt

        joblib.dump(
            {
                "model": model,
                "features": feats,
                "threshold": threshold,
                "target": "future_sla_event",
                "censoring": "task-lifecycle-aware",
            },
            out.models / f"{name}_final.joblib",
        )

    metrics_df = pd.DataFrame(rows)
    metrics_df.to_csv(
        out.prediction / "classical_baseline_metrics.csv",
        index=False,
    )
    pred.to_csv(
        out.prediction / "classical_test_predictions.csv",
        index=False,
    )

    return metrics_df, pred


# =============================================================================
# Prediction: quantum kernel + actual HCQKL blending
# =============================================================================

def quantum_statevectors(Z: np.ndarray) -> np.ndarray:
    from qiskit.quantum_info import Statevector

    try:
        from qiskit.circuit.library import zz_feature_map

        fmap = zz_feature_map(
            feature_dimension=Z.shape[1],
            reps=2,
            entanglement="linear",
        )
    except Exception:
        from qiskit.circuit.library import ZZFeatureMap

        fmap = ZZFeatureMap(
            feature_dimension=Z.shape[1],
            reps=2,
            entanglement="linear",
        )

    states = []

    for row in Z:
        qc = fmap.assign_parameters(
            row,
            inplace=False,
        )
        states.append(
            np.asarray(
                Statevector.from_instruction(qc).data,
                complex,
            )
        )

    return np.vstack(states)


def fidelity(A: np.ndarray, B: np.ndarray) -> np.ndarray:
    return np.abs(
        A @ B.conj().T
    ) ** 2


def fit_calibrator(
    scores: np.ndarray,
    y: np.ndarray,
):
    if len(np.unique(y)) < 2:
        raise RuntimeError(
            "Calibration interval contains one class only."
        )

    lr = LogisticRegression(
        solver="lbfgs",
        random_state=SEED,
    )
    lr.fit(
        np.asarray(scores).reshape(-1, 1),
        y,
    )
    return lr


def fit_kernel_preprocessing(
    tr: pd.DataFrame,
    frames: list[pd.DataFrame],
    feats: list[str],
):
    imputer = SimpleImputer(strategy="median")
    scaler = RobustScaler()

    d = min(
        PCA_COMPONENTS,
        len(feats),
    )

    pca = PCA(
        n_components=d,
        random_state=SEED,
    )
    angle = MinMaxScaler(
        feature_range=(0.0, np.pi)
    )

    Xtr = imputer.fit_transform(
        numeric(tr, feats)
    )
    Xtr = scaler.fit_transform(Xtr)
    Ztr0 = pca.fit_transform(Xtr)
    Ztr = angle.fit_transform(Ztr0)

    transformed = []

    for frame in frames:
        X = imputer.transform(
            numeric(frame, feats)
        )
        X = scaler.transform(X)
        Z = pca.transform(X)
        Z = angle.transform(Z)
        transformed.append(Z)

    return (
        imputer,
        scaler,
        pca,
        angle,
        Ztr,
        transformed,
    )


def blocked_alpha_selection(
    tr: pd.DataFrame,
    val: pd.DataFrame,
    feats: list[str],
    fast: bool,
    out: Paths,
):
    """
    Stronger alpha selection than the earlier small single validation subset.

    First 70% of the temporal validation interval is divided into independent
    contiguous blocks. Each alpha is trained once and evaluated on every block.
    The final alpha is selected by mean block score:
        0.5*ROC-AUC + 0.5*PR-AUC.

    The last 30% of validation is held out for calibration/threshold selection.
    """
    val = val.sort_values(
        TIME_COLUMN,
        kind="mergesort",
    ).reset_index(drop=True)

    cut = int(len(val) * 0.70)
    val_select = val.iloc[:cut].copy()
    val_cal = val.iloc[cut:].copy()

    blocks_n = 3 if fast else KERNEL_ALPHA_BLOCKS
    block_max = 600 if fast else KERNEL_ALPHA_BLOCK_MAX

    edges = np.linspace(
        0,
        len(val_select),
        blocks_n + 1,
        dtype=int,
    )

    blocks = []

    for b in range(blocks_n):
        block = val_select.iloc[
            edges[b]:edges[b + 1]
        ].copy()
        block = natural_subsample(
            block,
            min(block_max, len(block)),
        )

        if (
            len(block) > 0
            and block["future_sla_event"].nunique() == 2
        ):
            blocks.append(block)

    if len(blocks) < 2:
        raise RuntimeError(
            "Too few two-class validation blocks for robust alpha selection."
        )

    (
        imputer,
        scaler,
        pca,
        angle,
        Ztr,
        Zblocks,
    ) = fit_kernel_preprocessing(
        tr,
        blocks,
        feats,
    )

    ytr = tr["future_sla_event"].to_numpy(int)

    gamma = 1.0 / max(
        Ztr.shape[1],
        1,
    )

    Kr_tr = rbf_kernel(
        Ztr,
        Ztr,
        gamma=gamma,
    )

    Str = quantum_statevectors(Ztr)
    Kq_tr = fidelity(Str, Str)

    block_kernels = []

    for frame, Zb in zip(
        blocks,
        Zblocks,
    ):
        Kr = rbf_kernel(
            Zb,
            Ztr,
            gamma=gamma,
        )
        Sb = quantum_statevectors(Zb)
        Kq = fidelity(Sb, Str)

        block_kernels.append(
            (
                frame,
                Kr,
                Kq,
            )
        )

    block_rows = []
    aggregate_rows = []
    alpha_models = {}

    for alpha in ALPHA_GRID:
        Kh_tr = (
            alpha * Kr_tr
            + (1.0 - alpha) * Kq_tr
        )

        svc = SVC(
            kernel="precomputed",
            C=10,
            class_weight="balanced",
            probability=False,
            random_state=SEED,
        )
        svc.fit(
            Kh_tr,
            ytr,
        )

        alpha_models[float(alpha)] = svc

        scores = []

        for bidx, (
            block,
            Kr,
            Kq,
        ) in enumerate(block_kernels):
            Kh = (
                alpha * Kr
                + (1.0 - alpha) * Kq
            )
            d = svc.decision_function(Kh)
            y = block[
                "future_sla_event"
            ].to_numpy(int)

            roc = float(
                roc_auc_score(y, d)
            )
            pr = float(
                average_precision_score(y, d)
            )
            selection = (
                0.5 * roc
                + 0.5 * pr
            )

            scores.append(selection)

            block_rows.append({
                "alpha_rbf": float(alpha),
                "alpha_quantum": float(
                    1.0 - alpha
                ),
                "block": bidx,
                "rows": len(block),
                "positives": int(y.sum()),
                "prevalence": float(y.mean()),
                "roc_auc": roc,
                "pr_auc": pr,
                "selection_score": selection,
                "time_min": float(
                    block[TIME_COLUMN].min()
                ),
                "time_max": float(
                    block[TIME_COLUMN].max()
                ),
            })

        per_alpha = pd.DataFrame(
            [
                r for r in block_rows
                if math.isclose(
                    r["alpha_rbf"],
                    float(alpha),
                )
            ]
        )

        aggregate_rows.append({
            "alpha_rbf": float(alpha),
            "alpha_quantum": float(
                1.0 - alpha
            ),
            "valid_blocks": len(per_alpha),
            "mean_roc_auc": float(
                per_alpha["roc_auc"].mean()
            ),
            "mean_pr_auc": float(
                per_alpha["pr_auc"].mean()
            ),
            "mean_selection_score": float(
                per_alpha["selection_score"].mean()
            ),
            "median_selection_score": float(
                per_alpha["selection_score"].median()
            ),
            "selection_std": float(
                per_alpha["selection_score"].std(ddof=1)
            ) if len(per_alpha) > 1 else np.nan,
        })

    block_df = pd.DataFrame(block_rows)
    aggregate_df = pd.DataFrame(
        aggregate_rows
    )

    ranked = aggregate_df.copy()
    ranked["distance_to_half"] = abs(
        ranked["alpha_rbf"] - 0.5
    )

    ranked = ranked.sort_values(
        [
            "mean_selection_score",
            "mean_pr_auc",
            "median_selection_score",
            "distance_to_half",
        ],
        ascending=[
            False,
            False,
            False,
            True,
        ],
    )

    best_alpha = float(
        ranked.iloc[0]["alpha_rbf"]
    )

    block_df.to_csv(
        out.prediction
        / "hcqkl_alpha_block_results.csv",
        index=False,
    )
    aggregate_df.to_csv(
        out.prediction
        / "hcqkl_alpha_sweep.csv",
        index=False,
    )

    return {
        "best_alpha": best_alpha,
        "val_cal": val_cal,
        "imputer": imputer,
        "scaler": scaler,
        "pca": pca,
        "angle_scaler": angle,
        "z_train": Ztr,
        "statevectors_train": Str,
        "rbf_gamma": gamma,
        "K_rbf_train": Kr_tr,
        "K_quantum_train": Kq_tr,
        "alpha_models": alpha_models,
        "block_results": block_df,
        "aggregate_results": aggregate_df,
    }


def transform_with_kernel_prep(
    frame: pd.DataFrame,
    prep: dict[str, Any],
    feats: list[str],
):
    X = prep["imputer"].transform(
        numeric(frame, feats)
    )
    X = prep["scaler"].transform(X)
    Z = prep["pca"].transform(X)
    Z = prep["angle_scaler"].transform(Z)
    return Z


def run_matched_kernels(
    train: pd.DataFrame,
    val: pd.DataFrame,
    test: pd.DataFrame,
    out: Paths,
    fast: bool,
):
    feats = [
        c for c in EARLY_FEATURES
        if c in train.columns
    ]

    tr = class_enriched_train(
        train,
        600 if fast else KERNEL_TRAIN_MAX,
        150 if fast else KERNEL_TRAIN_POSITIVE_MAX,
    )

    prep = blocked_alpha_selection(
        tr,
        val,
        feats,
        fast,
        out,
    )

    best_alpha = prep[
        "best_alpha"
    ]

    vc = natural_subsample(
        prep["val_cal"],
        min(
            1_000 if fast else KERNEL_CAL_MAX,
            len(prep["val_cal"]),
        ),
    )

    te = natural_subsample(
        test,
        min(
            1_500 if fast else KERNEL_TEST_MAX,
            len(test),
        ),
    )

    if vc["future_sla_event"].nunique() < 2:
        raise RuntimeError(
            "Natural calibration interval has one class only."
        )

    if te["future_sla_event"].nunique() < 2:
        raise RuntimeError(
            "Natural matched test subset has one class only."
        )

    Zvc = transform_with_kernel_prep(
        vc,
        prep,
        feats,
    )
    Zte = transform_with_kernel_prep(
        te,
        prep,
        feats,
    )

    Kr_vc = rbf_kernel(
        Zvc,
        prep["z_train"],
        gamma=prep["rbf_gamma"],
    )
    Kr_te = rbf_kernel(
        Zte,
        prep["z_train"],
        gamma=prep["rbf_gamma"],
    )

    Svc = quantum_statevectors(Zvc)
    Ste = quantum_statevectors(Zte)

    Kq_vc = fidelity(
        Svc,
        prep["statevectors_train"],
    )
    Kq_te = fidelity(
        Ste,
        prep["statevectors_train"],
    )

    np.save(
        out.kernels / "rbf_train.npy",
        prep["K_rbf_train"],
    )
    np.save(
        out.kernels / "rbf_test.npy",
        Kr_te,
    )
    np.save(
        out.kernels / "quantum_train.npy",
        prep["K_quantum_train"],
    )
    np.save(
        out.kernels / "quantum_test.npy",
        Kq_te,
    )

    ytr = tr[
        "future_sla_event"
    ].to_numpy(int)
    yvc = vc[
        "future_sla_event"
    ].to_numpy(int)
    yte = te[
        "future_sla_event"
    ].to_numpy(int)

    model_specs = {
        "RBF_kernel": (
            1.0,
            prep["K_rbf_train"],
            Kr_vc,
            Kr_te,
        ),
        "Quantum_fidelity_kernel": (
            0.0,
            prep["K_quantum_train"],
            Kq_vc,
            Kq_te,
        ),
        "HCQKL": (
            best_alpha,
            (
                best_alpha
                * prep["K_rbf_train"]
                + (1.0 - best_alpha)
                * prep["K_quantum_train"]
            ),
            (
                best_alpha
                * Kr_vc
                + (1.0 - best_alpha)
                * Kq_vc
            ),
            (
                best_alpha
                * Kr_te
                + (1.0 - best_alpha)
                * Kq_te
            ),
        ),
    }

    rows = []
    pred = pd.DataFrame({
        "_source_row": te[
            "_source_row"
        ].to_numpy(),
        TIME_COLUMN: te[
            TIME_COLUMN
        ].to_numpy(),
        "future_sla_event": yte,
    })

    fitted = {}

    for name, (
        alpha,
        Ktr,
        Kvc,
        Kte,
    ) in model_specs.items():
        start = time.perf_counter()

        svc = SVC(
            kernel="precomputed",
            C=10,
            class_weight="balanced",
            probability=False,
            random_state=SEED,
        )
        svc.fit(
            Ktr,
            ytr,
        )

        train_seconds = (
            time.perf_counter()
            - start
        )

        dvc = svc.decision_function(
            Kvc
        )
        calibrator = fit_calibrator(
            dvc,
            yvc,
        )
        pvc = calibrator.predict_proba(
            dvc.reshape(-1, 1)
        )[:, 1]
        threshold = choose_threshold(
            yvc,
            pvc,
        )

        infer_start = time.perf_counter()
        dte = svc.decision_function(
            Kte
        )
        pte = calibrator.predict_proba(
            dte.reshape(-1, 1)
        )[:, 1]
        inference_seconds = (
            time.perf_counter()
            - infer_start
        )

        rows.append({
            "model": name,
            "alpha_rbf": alpha,
            "alpha_quantum": 1.0 - alpha,
            "train_rows": len(tr),
            "validation_calibration_rows": len(vc),
            "test_rows": len(te),
            "train_seconds": train_seconds,
            "test_inference_seconds": inference_seconds,
            **classification_metrics(
                yte,
                pte,
                threshold,
            ),
        })

        pred[
            f"p_{name}"
        ] = pte

        fitted[name] = {
            "svc": svc,
            "calibrator": calibrator,
            "threshold": threshold,
        }

    metrics_df = pd.DataFrame(
        rows
    )

    metrics_df.to_csv(
        out.prediction
        / "matched_kernel_test_metrics.csv",
        index=False,
    )

    pred.to_csv(
        out.prediction
        / "matched_kernel_test_predictions_strict_subset.csv",
        index=False,
    )

    # Final downstream HCQKL objects.
    h = fitted["HCQKL"]

    bundle = {
        "target": "future_sla_event",
        "horizon_seconds": PRIMARY_HORIZON,
        "censoring": "task-lifecycle-aware",
        "features": feats,
        "imputer": prep["imputer"],
        "scaler": prep["scaler"],
        "pca": prep["pca"],
        "angle_scaler": prep["angle_scaler"],
        "z_train": prep["z_train"],
        "statevectors_train": prep["statevectors_train"],
        "rbf_gamma": prep["rbf_gamma"],
        "best_alpha": best_alpha,
        "hcqkl_svc": h["svc"],
        "hcqkl_calibrator": h["calibrator"],
        "hcqkl_threshold": h["threshold"],
        "training_source_rows": tr[
            "_source_row"
        ].to_numpy(),
        "alpha_selection": (
            "mean block-level 0.5*ROC-AUC + 0.5*PR-AUC "
            "across contiguous natural-prevalence temporal "
            "validation blocks"
        ),
    }

    joblib.dump(
        bundle,
        out.models / "hcqkl_v2_bundle.joblib",
    )
    joblib.dump(
        bundle,
        out.models / "hcqkl_final_lifecycle_bundle.joblib",
    )

    subset_summary = pd.DataFrame([
        {
            "subset": "train_class_enriched",
            "rows": len(tr),
            "positives": int(
                tr["future_sla_event"].sum()
            ),
            "prevalence": float(
                tr["future_sla_event"].mean()
            ),
        },
        {
            "subset": "validation_calibration_natural",
            "rows": len(vc),
            "positives": int(
                vc["future_sla_event"].sum()
            ),
            "prevalence": float(
                vc["future_sla_event"].mean()
            ),
        },
        {
            "subset": "test_natural",
            "rows": len(te),
            "positives": int(
                te["future_sla_event"].sum()
            ),
            "prevalence": float(
                te["future_sla_event"].mean()
            ),
        },
    ])

    subset_summary.to_csv(
        out.prediction
        / "matched_kernel_subset_summary.csv",
        index=False,
    )

    return (
        metrics_df,
        pred,
        bundle,
        prep["aggregate_results"],
    )


def score_hcqkl_full(
    frame: pd.DataFrame,
    bundle: dict[str, Any],
    chunk_size: int = 256,
) -> np.ndarray:
    feats = bundle[
        "features"
    ]

    probabilities = []

    for start in range(
        0,
        len(frame),
        chunk_size,
    ):
        chunk = frame.iloc[
            start:start + chunk_size
        ]

        X = bundle[
            "imputer"
        ].transform(
            numeric(
                chunk,
                feats,
            )
        )
        X = bundle[
            "scaler"
        ].transform(X)
        Z = bundle[
            "pca"
        ].transform(X)
        Z = bundle[
            "angle_scaler"
        ].transform(Z)

        Kr = rbf_kernel(
            Z,
            bundle["z_train"],
            gamma=bundle["rbf_gamma"],
        )

        S = quantum_statevectors(Z)

        Kq = fidelity(
            S,
            bundle["statevectors_train"],
        )

        alpha = float(
            bundle["best_alpha"]
        )

        Kh = (
            alpha * Kr
            + (1.0 - alpha) * Kq
        )

        d = bundle[
            "hcqkl_svc"
        ].decision_function(Kh)

        p = bundle[
            "hcqkl_calibrator"
        ].predict_proba(
            np.asarray(d).reshape(-1, 1)
        )[:, 1]

        probabilities.append(p)

    return np.concatenate(
        probabilities
    )


