def horizon_sensitivity(
    annotated: pd.DataFrame,
    clean_terminal_events: set[str],
    out: Paths,
    fast: bool,
):
    rows = []

    horizons = [PRIMARY_HORIZON] if fast else HORIZONS

    for H in horizons:
        data, _ = build_lifecycle_target(
            annotated,
            H,
            clean_terminal_events,
        )
        train, val, test = temporal_split(
            data
        )

        feats = [
            c for c in EARLY_FEATURES
            if c in data.columns
        ]

        tr = natural_subsample(
            train,
            min(
                15_000 if fast else CLASSICAL_TRAIN_MAX,
                len(train),
            ),
        )

        Xtr = numeric(
            tr,
            feats,
        )
        ytr = tr[
            "future_sla_event"
        ].to_numpy(int)

        Xv = numeric(
            val,
            feats,
        )
        yv = val[
            "future_sla_event"
        ].to_numpy(int)

        Xt = numeric(
            test,
            feats,
        )
        yt = test[
            "future_sla_event"
        ].to_numpy(int)

        model = Pipeline([
            (
                "imputer",
                SimpleImputer(
                    strategy="median"
                ),
            ),
            (
                "scaler",
                RobustScaler(),
            ),
            (
                "clf",
                HistGradientBoostingClassifier(
                    learning_rate=0.05,
                    max_iter=250,
                    max_leaf_nodes=31,
                    min_samples_leaf=20,
                    l2_regularization=1.0,
                    random_state=SEED,
                ),
            ),
        ])

        sw = compute_sample_weight(
            "balanced",
            ytr,
        )
        model.fit(
            Xtr,
            ytr,
            clf__sample_weight=sw,
        )

        pv = model.predict_proba(
            Xv
        )[:, 1]
        t = choose_threshold(
            yv,
            pv,
        )
        pt = model.predict_proba(
            Xt
        )[:, 1]

        rows.append({
            "horizon_seconds": H,
            "eligible_rows": len(data),
            "positives": int(
                data["future_sla_event"].sum()
            ),
            "overall_prevalence": float(
                data["future_sla_event"].mean()
            ),
            **classification_metrics(
                yt,
                pt,
                t,
            ),
        })

    ans = pd.DataFrame(rows)
    ans.to_csv(
        out.ablations
        / "horizon_sensitivity.csv",
        index=False,
    )
    return ans


