# =============================================================================
# Deterministic heterogeneous temporal instance selection
# =============================================================================

def _task_identity_columns(df: pd.DataFrame) -> list[str]:
    cols = [c for c in TASK_KEYS if c in df.columns]
    if len(cols) == len(TASK_KEYS):
        return cols
    if "record_id" in df.columns:
        return ["record_id"]
    return ["_source_row"]


def _robust_scale_vector(v: pd.Series) -> np.ndarray:
    x = pd.to_numeric(v, errors="coerce").to_numpy(float)
    finite = np.isfinite(x)
    if finite.any():
        fill = float(np.nanmedian(x[finite]))
    else:
        fill = 0.0
    x = np.where(finite, x, fill)

    lo = float(np.quantile(x, 0.05))
    hi = float(np.quantile(x, 0.95))
    span = hi - lo
    if not np.isfinite(span) or span <= 1e-12:
        span = float(np.std(x))
    if not np.isfinite(span) or span <= 1e-12:
        span = 1.0
    return (x - float(np.median(x))) / span


def _selection_matrix(
    candidates: pd.DataFrame,
) -> tuple[np.ndarray, list[str]]:
    """
    Decision-time / model-output features only.
    No realized duration, SLO outcome, event label, or QAOA result is used.
    """
    arrays = []
    names = []

    numeric_specs = [
        ("risk_hcqkl", 1.50),
        ("requested_cpu", 1.00),
        ("requested_memory", 1.00),
        ("_estimated_duration_selection", 1.00),
        ("priority", 0.50),
    ]

    for col, weight in numeric_specs:
        if col in candidates.columns:
            arrays.append(
                weight
                * _robust_scale_vector(
                    candidates[col]
                )
            )
            names.append(col)

    for col, weight in [
        ("scheduling_class", 0.50),
        ("collection_type", 0.35),
        ("scheduler", 0.25),
    ]:
        if col in candidates.columns:
            codes, _ = pd.factorize(
                candidates[col].astype(str),
                sort=True,
            )
            arrays.append(
                weight
                * _robust_scale_vector(
                    pd.Series(codes)
                )
            )
            names.append(col)

    if not arrays:
        raise RuntimeError(
            "No valid decision-time features available for heterogeneous "
            "instance selection."
        )

    X = np.column_stack(arrays).astype(float)
    return X, names


def _pairwise_distance_summary(X: np.ndarray) -> dict[str, float]:
    if len(X) < 2:
        return {
            "mean_pairwise_distance": 0.0,
            "min_pairwise_distance": 0.0,
            "max_pairwise_distance": 0.0,
        }

    d = []
    for i in range(len(X)):
        for j in range(i + 1, len(X)):
            d.append(
                float(
                    np.linalg.norm(
                        X[i] - X[j]
                    )
                )
            )

    arr = np.asarray(d, float)
    return {
        "mean_pairwise_distance": float(arr.mean()),
        "min_pairwise_distance": float(arr.min()),
        "max_pairwise_distance": float(arr.max()),
    }


def _unique_candidates(
    segment: pd.DataFrame,
    max_candidates: int = 600,
) -> pd.DataFrame:
    ids = _task_identity_columns(segment)

    c = (
        segment
        .sort_values(
            TIME_COLUMN,
            kind="mergesort",
        )
        .drop_duplicates(
            subset=ids,
            keep="first",
        )
        .copy()
    )

    if len(c) > max_candidates:
        idx = np.linspace(
            0,
            len(c) - 1,
            max_candidates,
            dtype=int,
        )
        c = c.iloc[idx].copy()

    return c.reset_index(drop=True)


def select_heterogeneous_batch(
    segment: pd.DataFrame,
    batch_size: int,
    block: int,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """
    Deterministic farthest-point selection inside one contiguous temporal block.

    The rule is fixed and solver-independent:
      1) remove repeated task identities;
      2) form a standardized vector from predicted risk, requested resources,
         training-derived estimated duration, and scheduling context;
      3) choose the point farthest from the block center;
      4) iteratively choose the point maximizing minimum distance from the
         already selected set.

    This avoids near-duplicate trace snapshots while preserving temporal blocks.
    """
    candidates = _unique_candidates(
        segment,
        max_candidates=600,
    )

    if len(candidates) < batch_size:
        raise RuntimeError(
            f"Temporal block {block} has only {len(candidates)} unique tasks "
            f"for requested batch size {batch_size}."
        )

    X, feature_names = _selection_matrix(
        candidates
    )

    center = np.median(
        X,
        axis=0,
    )

    first = int(
        np.argmax(
            np.linalg.norm(
                X - center,
                axis=1,
            )
        )
    )

    chosen = [first]

    while len(chosen) < batch_size:
        remaining = [
            i for i in range(len(candidates))
            if i not in chosen
        ]

        best_i = None
        best_score = -np.inf

        for i in remaining:
            min_dist = min(
                float(
                    np.linalg.norm(
                        X[i] - X[j]
                    )
                )
                for j in chosen
            )

            # deterministic tie-break by earlier time then source row
            score = min_dist
            if score > best_score + 1e-12:
                best_i = i
                best_score = score

        if best_i is None:
            break

        chosen.append(
            int(best_i)
        )

    selected = (
        candidates.iloc[chosen]
        .sort_values(
            TIME_COLUMN,
            kind="mergesort",
        )
        .reset_index(drop=True)
    )

    selected_X, _ = _selection_matrix(
        selected
    )

    diag = {
        "block": int(block),
        "batch_size": int(batch_size),
        "candidate_unique_tasks": int(
            len(candidates)
        ),
        "selection_features": feature_names,
        "selected_unique_task_count": int(
            len(selected)
        ),
        "risk_min": float(
            pd.to_numeric(
                selected["risk_hcqkl"],
                errors="coerce",
            ).min()
        ),
        "risk_max": float(
            pd.to_numeric(
                selected["risk_hcqkl"],
                errors="coerce",
            ).max()
        ),
        "risk_std": float(
            pd.to_numeric(
                selected["risk_hcqkl"],
                errors="coerce",
            ).std(ddof=0)
        ),
        "cpu_unique": int(
            pd.to_numeric(
                selected["requested_cpu"],
                errors="coerce",
            ).nunique(dropna=True)
        ),
        "memory_unique": int(
            pd.to_numeric(
                selected["requested_memory"],
                errors="coerce",
            ).nunique(dropna=True)
        ),
        "estimated_duration_unique": int(
            pd.to_numeric(
                selected["_estimated_duration_selection"],
                errors="coerce",
            ).nunique(dropna=True)
        ),
        "time_min": float(
            selected[TIME_COLUMN].min()
        ),
        "time_max": float(
            selected[TIME_COLUMN].max()
        ),
        **_pairwise_distance_summary(
            selected_X
        ),
    }

    return selected, diag


def heterogeneous_temporal_batches(
    pool: pd.DataFrame,
    batch_size: int,
    blocks: int,
) -> list[tuple[int, pd.DataFrame, dict[str, Any]]]:
    """
    Split the untouched temporal test pool into contiguous non-overlapping
    index blocks, then select a heterogeneous task set inside each block.
    """
    n = len(pool)

    if n < batch_size:
        return []

    edges = np.linspace(
        0,
        n,
        blocks + 1,
        dtype=int,
    )

    result = []

    for block in range(blocks):
        lo = int(
            edges[block]
        )
        hi = int(
            edges[block + 1]
        )

        if hi - lo < batch_size:
            continue

        segment = pool.iloc[
            lo:hi
        ].copy()

        try:
            batch, diag = select_heterogeneous_batch(
                segment,
                batch_size,
                block,
            )
        except RuntimeError:
            # Deterministic local expansion only when a block contains too
            # few distinct task identities.
            pad = max(
                batch_size * 20,
                (hi - lo) // 2,
            )
            elo = max(
                0,
                lo - pad,
            )
            ehi = min(
                n,
                hi + pad,
            )
            segment = pool.iloc[
                elo:ehi
            ].copy()
            batch, diag = select_heterogeneous_batch(
                segment,
                batch_size,
                block,
            )
            diag[
                "expanded_temporal_window"
            ] = True
            diag[
                "expanded_index_low"
            ] = int(elo)
            diag[
                "expanded_index_high"
            ] = int(ehi)

        result.append(
            (
                block,
                batch,
                diag,
            )
        )

    return result


# =============================================================================
# Robust QAOA worker defined in the PHYSICAL final script
# =============================================================================

def _final_qaoa_sampler(
    shots: int,
    seed: int,
):
    try:
        from qiskit.primitives import StatevectorSampler

        return (
            StatevectorSampler(
                default_shots=int(shots),
                seed=int(seed),
            ),
            "StatevectorSampler",
        )
    except Exception:
        from qiskit.primitives import Sampler

        return (
            Sampler(
                options={
                    "shots": int(shots),
                    "seed": int(seed),
                }
            ),
            "Sampler",
        )


def _final_qaoa_worker(
    payload: dict[str, Any],
    queue,
) -> None:
    """
    Windows-safe multiprocessing target.

    This function lives in the physical 35_*.py file, so the spawned child can
    import it through __mp_main__. It does NOT depend on a dynamically imported
    helper module as the multiprocessing target.
    """
    try:
        try:
            from qiskit_algorithms.minimum_eigensolvers import QAOA
            from qiskit_algorithms.optimizers import COBYLA

            try:
                from qiskit_algorithms.utils import algorithm_globals

                algorithm_globals.random_seed = int(
                    payload["seed"]
                )
            except Exception:
                pass

        except Exception:
            from qiskit.algorithms.minimum_eigensolvers import QAOA
            from qiskit.algorithms.optimizers import COBYLA

        from qiskit_optimization import QuadraticProgram
        from qiskit_optimization.algorithms import MinimumEigenOptimizer

        qp = QuadraticProgram(
            "aqua_sla_final_compact_qubo"
        )

        for i in range(2):
            for j in range(2):
                qp.binary_var(
                    f"x_{i}_{j}"
                )

        quadratic = {}
        for key, value in payload[
            "quadratic"
        ].items():
            a, b = key.split(
                "|",
                1,
            )
            quadratic[
                (a, b)
            ] = float(value)

        qp.minimize(
            constant=float(
                payload["constant"]
            ),
            linear={
                k: float(v)
                for k, v in payload[
                    "linear"
                ].items()
            },
            quadratic=quadratic,
        )

        sampler, sampler_name = (
            _final_qaoa_sampler(
                int(payload["shots"]),
                int(payload["seed"]),
            )
        )

        qaoa = QAOA(
            sampler=sampler,
            optimizer=COBYLA(
                maxiter=int(
                    payload["maxiter"]
                )
            ),
            reps=int(
                payload["reps"]
            ),
        )

        optimizer = MinimumEigenOptimizer(
            qaoa
        )

        start = time.perf_counter()

        result = optimizer.solve(
            qp
        )

        elapsed = (
            time.perf_counter()
            - start
        )

        x = np.asarray(
            result.x,
            dtype=float,
        )

        bits = (
            x >= 0.5
        ).astype(int).tolist()

        queue.put(
            {
                "success": True,
                "timed_out": False,
                "sampler": sampler_name,
                "elapsed_seconds": elapsed,
                "status": str(
                    getattr(
                        result,
                        "status",
                        "unknown",
                    )
                ),
                "raw_x": x.tolist(),
                "raw_bits": bits,
                "fval": (
                    float(
                        result.fval
                    )
                    if getattr(
                        result,
                        "fval",
                        None,
                    )
                    is not None
                    else None
                ),
            }
        )

    except Exception as exc:
        queue.put(
            {
                "success": False,
                "timed_out": False,
                "error_stage": "qaoa_worker",
                "error": repr(exc),
            }
        )


def run_final_qaoa_timeout(
    payload: dict[str, Any],
    timeout_seconds: int,
) -> dict[str, Any]:
    ctx = mp.get_context(
        "spawn"
    )

    queue = ctx.Queue()

    process = ctx.Process(
        target=_final_qaoa_worker,
        args=(
            payload,
            queue,
        ),
    )

    start = time.perf_counter()

    process.start()
    process.join(
        timeout_seconds
    )

    wall = (
        time.perf_counter()
        - start
    )

    if process.is_alive():
        process.terminate()
        process.join(10)

        return {
            "success": False,
            "timed_out": True,
            "timeout_seconds": int(
                timeout_seconds
            ),
            "wall_seconds": wall,
            "error_stage": "wall_clock_timeout",
            "error": (
                f"QAOA exceeded {timeout_seconds} seconds "
                "and was terminated."
            ),
            "worker_exit_code": process.exitcode,
        }

    try:
        result = queue.get(
            timeout=2.0
        )
        result[
            "wall_seconds"
        ] = wall
        result[
            "worker_exit_code"
        ] = process.exitcode
        return result

    except Exception:
        return {
            "success": False,
            "timed_out": False,
            "wall_seconds": wall,
            "error_stage": "worker_no_result",
            "error": (
                f"QAOA worker exited with code {process.exitcode} "
                "without returning a result."
            ),
            "worker_exit_code": process.exitcode,
        }


def _cost_matrix_row_distance(
    C: np.ndarray,
) -> float:
    if C.shape[0] < 2:
        return 0.0
    return float(
        np.linalg.norm(
            C[0] - C[1]
        )
    )


def _feasible_assignment_objectives(
    helper30,
    batch: pd.DataFrame,
    resources,
    C: np.ndarray,
) -> list[float]:
    vals = []
    for a0 in range(
        len(resources)
    ):
        for a1 in range(
            len(resources)
        ):
            a = [
                a0,
                a1,
            ]
            if helper30.assignment_feasible(
                a,
                batch,
                resources,
            ):
                vals.append(
                    helper30.assignment_objective(
                        a,
                        C,
                    )
                )
    return vals


# =============================================================================
# Classical capacity-aware scheduling
# =============================================================================

def least_loaded(
    batch: pd.DataFrame,
    resources,
    C: np.ndarray,
    duration_medians: dict[str, float],
    global_median: float,
):
    start = time.perf_counter()

    cpu = pd.to_numeric(
        batch["requested_cpu"],
        errors="coerce",
    ).fillna(0).to_numpy(float)

    mem = pd.to_numeric(
        batch["requested_memory"],
        errors="coerce",
    ).fillna(0).to_numpy(float)

    classes = (
        batch["scheduling_class"].astype(str)
        if "scheduling_class" in batch
        else pd.Series(["global"] * len(batch))
    )

    dur = np.array(
        [
            duration_medians.get(
                str(c),
                global_median,
            )
            for c in classes
        ],
        dtype=float,
    )

    used_cpu = np.zeros(
        len(resources)
    )
    used_mem = np.zeros(
        len(resources)
    )
    projected_load = np.zeros(
        len(resources)
    )

    assignment = [-1] * len(batch)

    order = np.argsort(
        pd.to_numeric(
            batch[TIME_COLUMN],
            errors="coerce",
        ).to_numpy(float)
    )

    for i in order:
        candidates = []

        for j, r in enumerate(resources):
            if (
                used_cpu[j] + cpu[i]
                <= r.cpu_capacity + 1e-9
                and used_mem[j] + mem[i]
                <= r.memory_capacity + 1e-9
            ):
                candidates.append(j)

        if not candidates:
            return None, (
                time.perf_counter()
                - start
            )

        j = min(
            candidates,
            key=lambda jj: (
                projected_load[jj],
                C[i, jj],
                jj,
            ),
        )

        assignment[i] = int(j)
        used_cpu[j] += cpu[i]
        used_mem[j] += mem[i]
        projected_load[j] += (
            dur[i] / resources[j].speed
        )

    return assignment, (
        time.perf_counter()
        - start
    )


def add_sched_result(
    rows: list[dict[str, Any]],
    helper30,
    batch_size: int,
    block: int,
    solver: str,
    batch: pd.DataFrame,
    resources,
    C: np.ndarray,
    assignment,
    runtime: float | None,
    milp_obj: float,
    slos,
    global_slo,
):
    if assignment is None:
        rows.append({
            "batch_size": batch_size,
            "block": block,
            "instance_id": (
                f"bs{batch_size}_block{block:02d}"
            ),
            "solver": solver,
            "completed": False,
            "feasible": False,
            "runtime_seconds": runtime,
            "objective": np.nan,
            "milp_objective": milp_obj,
            "objective_gap": np.nan,
            "relative_objective_gap": np.nan,
        })
        return

    feasible = helper30.assignment_feasible(
        assignment,
        batch,
        resources,
    )

    objective = helper30.assignment_objective(
        assignment,
        C,
    )

    ext = (
        helper30.evaluate_external_slo(
            batch,
            resources,
            assignment,
            slos,
            global_slo,
        )
        if feasible
        else {
            k: np.nan
            for k in [
                "slo_miss_rate",
                "mean_waiting",
                "mean_completion",
                "makespan",
                "total_energy",
                "total_cost",
            ]
        }
    )

    gap = (
        objective - milp_obj
        if np.isfinite(milp_obj)
        else np.nan
    )

    rows.append({
        "batch_size": batch_size,
        "block": block,
        "instance_id": (
            f"bs{batch_size}_block{block:02d}"
        ),
        "solver": solver,
        "completed": True,
        "feasible": bool(feasible),
        "runtime_seconds": runtime,
        "objective": objective,
        "milp_objective": milp_obj,
        "objective_gap": gap,
        "relative_objective_gap": (
            gap / max(
                abs(milp_obj),
                1e-12,
            )
            if np.isfinite(gap)
            else np.nan
        ),
        "assignment": json.dumps(
            assignment
        ),
        **ext,
    })


def run_capacity_scheduling(
    train: pd.DataFrame,
    test_scored: pd.DataFrame,
    out: Paths,
    helper30,
    fast: bool,
):
    pool = test_scored.copy()

    required = [
        TIME_COLUMN,
        "requested_cpu",
        "requested_memory",
        "duration_seconds",
        "risk_hcqkl",
    ]

    for c in required:
        pool[c] = pd.to_numeric(
            pool[c],
            errors="coerce",
        )

    pool = pool.dropna(
        subset=required
    )

    pool = pool[
        (pool["requested_cpu"] > 0)
        & (pool["requested_memory"] > 0)
        & (pool["duration_seconds"] > 0)
    ].sort_values(
        TIME_COLUMN,
        kind="mergesort",
    ).reset_index(drop=True)

    (
        medians,
        global_median,
        slos,
        global_slo,
    ) = helper30.train_duration_tables(
        train
    )

    if "scheduling_class" in pool.columns:
        pool[
            "_estimated_duration_selection"
        ] = [
            medians.get(
                str(c),
                global_median,
            )
            for c in pool[
                "scheduling_class"
            ].astype(str)
        ]
    else:
        pool[
            "_estimated_duration_selection"
        ] = global_median

    save_json(
        {
            "external_slo_definition": (
                "training-period 90th percentile observed duration "
                "by scheduling class, with global 90th percentile fallback"
            ),
            "assignment_objective_contains_realized_slo_outcome": False,
            "test_label_used_in_assignment": False,
            "instance_selection_uses_realized_duration": False,
            "instance_selection": (
                "deterministic diversity-stratified selection inside "
                "non-overlapping temporal test blocks using predicted risk, "
                "requested CPU/memory, training-derived estimated duration, "
                "and scheduling context; repeated task identities are removed"
            ),
            "post_assignment_outcomes": [
                "slo_miss_rate",
                "mean_waiting",
                "mean_completion",
                "makespan",
                "total_energy",
                "total_cost",
            ],
            "global_slo_seconds": global_slo,
        },
        out.scheduling
        / "external_slo_definition.json",
    )

    rng = np.random.default_rng(
        SEED
    )

    rows = []
    diversity_rows = []

    batch_sizes = (
        [4]
        if fast
        else SCHED_BATCH_SIZES
    )

    blocks = (
        5
        if fast
        else SCHED_BLOCKS
    )

    for bs in batch_sizes:
        batches = heterogeneous_temporal_batches(
            pool,
            bs,
            blocks,
        )

        for (
            block,
            batch,
            diag,
        ) in batches:
            resources = helper30.resources_for(
                batch,
                SCHED_RESOURCES,
            )

            C = helper30.cost_matrix(
                batch,
                resources,
                medians,
                global_median,
            )

            row_spread = float(
                np.mean(
                    np.linalg.norm(
                        C
                        - C.mean(
                            axis=0,
                            keepdims=True,
                        ),
                        axis=1,
                    )
                )
            )

            diag.update(
                {
                    "solver_cost_row_spread": row_spread,
                    "preferred_resource_unique": int(
                        len(
                            np.unique(
                                np.argmin(
                                    C,
                                    axis=1,
                                )
                            )
                        )
                    ),
                }
            )
            diversity_rows.append(
                diag
            )

            (
                milp_a,
                milp_obj,
                milp_rt,
                milp_status,
            ) = helper30.solve_milp(
                batch,
                resources,
                C,
            )

            add_sched_result(
                rows,
                helper30,
                bs,
                block,
                "MILP",
                batch,
                resources,
                C,
                milp_a,
                milp_rt,
                milp_obj,
                slos,
                global_slo,
            )

            greedy_a, greedy_rt = (
                helper30.risk_greedy(
                    batch,
                    resources,
                    C,
                )
            )
            add_sched_result(
                rows,
                helper30,
                bs,
                block,
                "RiskGreedy",
                batch,
                resources,
                C,
                greedy_a,
                greedy_rt,
                milp_obj,
                slos,
                global_slo,
            )

            loaded_a, loaded_rt = least_loaded(
                batch,
                resources,
                C,
                medians,
                global_median,
            )
            add_sched_result(
                rows,
                helper30,
                bs,
                block,
                "LeastLoaded",
                batch,
                resources,
                C,
                loaded_a,
                loaded_rt,
                milp_obj,
                slos,
                global_slo,
            )

            random_a, random_rt = (
                helper30.random_feasible(
                    batch,
                    resources,
                    rng,
                )
            )
            add_sched_result(
                rows,
                helper30,
                bs,
                block,
                "RandomFeasible",
                batch,
                resources,
                C,
                random_a,
                random_rt,
                milp_obj,
                slos,
                global_slo,
            )

            block_dir = (
                out.scheduling
                / "instances"
                / f"bs{bs}_block{block:02d}"
            )
            block_dir.mkdir(
                parents=True,
                exist_ok=True,
            )

            batch.to_csv(
                block_dir
                / "selected_tasks.csv",
                index=False,
            )

            pd.DataFrame(C).to_csv(
                block_dir
                / "cost_matrix.csv",
                index=False,
            )

            pd.DataFrame(
                [
                    asdict(r)
                    for r in resources
                ]
            ).to_csv(
                block_dir
                / "resource_profiles.csv",
                index=False,
            )

            save_json(
                {
                    "batch_size": bs,
                    "block": block,
                    "milp_status": milp_status,
                    "diversity": diag,
                },
                block_dir
                / "instance_manifest.json",
            )

    results = pd.DataFrame(
        rows
    )

    results.to_csv(
        out.scheduling
        / "capacity_scheduling_results.csv",
        index=False,
    )

    diversity_df = pd.DataFrame(
        diversity_rows
    )
    diversity_df.to_csv(
        out.scheduling
        / "instance_diversity_audit.csv",
        index=False,
    )

    summary = (
        results
        .groupby(
            [
                "batch_size",
                "solver",
            ],
            as_index=False,
        )
        .agg(
            instances=("block", "count"),
            completion_rate=(
                "completed",
                "mean",
            ),
            feasibility_rate=(
                "feasible",
                "mean",
            ),
            mean_objective=(
                "objective",
                "mean",
            ),
            mean_objective_gap=(
                "objective_gap",
                "mean",
            ),
            mean_slo_miss=(
                "slo_miss_rate",
                "mean",
            ),
            mean_waiting=(
                "mean_waiting",
                "mean",
            ),
            mean_completion=(
                "mean_completion",
                "mean",
            ),
            mean_makespan=(
                "makespan",
                "mean",
            ),
            mean_energy=(
                "total_energy",
                "mean",
            ),
            mean_cost=(
                "total_cost",
                "mean",
            ),
            mean_runtime_seconds=(
                "runtime_seconds",
                "mean",
            ),
        )
    )

    summary.to_csv(
        out.scheduling
        / "capacity_scheduling_summary.csv",
        index=False,
    )

    return results, summary


def scheduling_statistics(
    results: pd.DataFrame,
    out: Paths,
    bootstrap: int,
):
    metrics = [
        "objective",
        "slo_miss_rate",
        "mean_waiting",
        "mean_completion",
        "makespan",
        "total_energy",
        "total_cost",
        "runtime_seconds",
    ]

    solvers = [
        s
        for s in results[
            "solver"
        ].unique()
        if s != "MILP"
    ]

    rows = []

    for solver in solvers:
        for metric in metrics:
            a = (
                results[
                    (results["solver"] == solver)
                    & results[metric].notna()
                ][
                    [
                        "batch_size",
                        "block",
                        metric,
                    ]
                ]
                .rename(
                    columns={
                        metric: "a"
                    }
                )
            )

            b = (
                results[
                    (results["solver"] == "MILP")
                    & results[metric].notna()
                ][
                    [
                        "batch_size",
                        "block",
                        metric,
                    ]
                ]
                .rename(
                    columns={
                        metric: "b"
                    }
                )
            )

            paired = a.merge(
                b,
                on=[
                    "batch_size",
                    "block",
                ],
                how="inner",
            )

            if paired.empty:
                continue

            d = (
                paired["a"].to_numpy(float)
                - paired["b"].to_numpy(float)
            )

            lo, hi = bootstrap_ci(
                d,
                bootstrap,
                SEED + len(rows),
            )

            nz = d[
                ~np.isclose(
                    d,
                    0,
                )
            ]

            stat = np.nan
            p = np.nan

            if len(nz) >= 6:
                try:
                    w = wilcoxon(
                        nz,
                        alternative="two-sided",
                        zero_method="wilcox",
                        method="auto",
                    )
                    stat = float(
                        w.statistic
                    )
                    p = float(
                        w.pvalue
                    )
                except Exception:
                    pass

            rows.append({
                "solver_a": solver,
                "solver_b": "MILP",
                "metric": metric,
                "pairs": len(paired),
                "mean_a": float(
                    paired["a"].mean()
                ),
                "mean_b": float(
                    paired["b"].mean()
                ),
                "mean_diff_a_minus_b": float(
                    d.mean()
                ),
                "median_diff_a_minus_b": float(
                    np.median(d)
                ),
                "bootstrap95_low": lo,
                "bootstrap95_high": hi,
                "paired_cohens_dz": (
                    paired_cohens_dz(d)
                ),
                "wilcoxon_stat": stat,
                "p_raw": p,
            })

    ans = pd.DataFrame(rows)

    if not ans.empty:
        ans["p_holm"] = holm_adjust(
            ans["p_raw"].to_numpy(float)
        )
        ans[
            "significant_holm_0_05"
        ] = (
            ans["p_holm"] < 0.05
        )

    ans.to_csv(
        out.statistics
        / "capacity_scheduling_paired_statistics.csv",
        index=False,
    )

    return ans


