def make_final_figures(
    audit: pd.DataFrame,
    baseline: pd.DataFrame,
    kernel: pd.DataFrame,
    scheduling_summary: pd.DataFrame,
    alpha: pd.DataFrame,
    out: Paths,
):
    try:
        import matplotlib.pyplot as plt
    except Exception:
        return

    if not audit.empty:
        fig, ax = plt.subplots(
            figsize=(7, 4.5)
        )
        x = np.arange(
            len(audit)
        )
        w = 0.35

        ax.bar(
            x - w / 2,
            audit[
                "old_global_only_eligible"
            ],
            w,
            label="Global-only",
        )
        ax.bar(
            x + w / 2,
            audit[
                "strict_lifecycle_eligible"
            ],
            w,
            label="Task-lifecycle",
        )
        ax.set_xticks(x)
        ax.set_xticklabels(
            [
                f"{int(v)} s"
                for v in audit[
                    "horizon_seconds"
                ]
            ]
        )
        ax.set_ylabel(
            "Eligible observations"
        )
        ax.set_title(
            "Task-lifecycle censoring audit"
        )
        ax.legend()
        fig.tight_layout()
        fig.savefig(
            out.figures
            / "target_censoring_audit.png",
            dpi=300,
        )
        plt.close(fig)

    combined = []

    for _, r in baseline.iterrows():
        combined.append({
            "model": r["model"],
            "roc_auc": r["roc_auc"],
        })

    for _, r in kernel.iterrows():
        combined.append({
            "model": r["model"],
            "roc_auc": r["roc_auc"],
        })

    if combined:
        z = (
            pd.DataFrame(combined)
            .sort_values(
                "roc_auc"
            )
        )
        fig, ax = plt.subplots(
            figsize=(8, 5)
        )
        ax.barh(
            z["model"],
            z["roc_auc"],
        )
        ax.set_xlim(
            0,
            1,
        )
        ax.set_xlabel(
            "ROC-AUC"
        )
        ax.set_title(
            "Lifecycle-censored future-horizon prediction"
        )
        fig.tight_layout()
        fig.savefig(
            out.figures
            / "prediction_roc_auc.png",
            dpi=300,
        )
        plt.close(fig)

    if not alpha.empty:
        fig, ax = plt.subplots(
            figsize=(7, 4.5)
        )
        ax.plot(
            alpha["alpha_rbf"],
            alpha[
                "mean_selection_score"
            ],
            marker="o",
        )
        ax.set_xlabel(
            r"$\alpha$ (RBF kernel weight)"
        )
        ax.set_ylabel(
            "Mean blocked validation selection score"
        )
        ax.set_title(
            "HCQKL blending sensitivity"
        )
        ax.grid(
            alpha=0.25
        )
        fig.tight_layout()
        fig.savefig(
            out.figures
            / "hcqkl_alpha_sensitivity.png",
            dpi=300,
        )
        plt.close(fig)

    if not scheduling_summary.empty:
        z = scheduling_summary.copy()

        fig, ax = plt.subplots(
            figsize=(8, 4.5)
        )

        for solver, g in z.groupby(
            "solver"
        ):
            ax.plot(
                g["batch_size"],
                g["mean_slo_miss"],
                marker="o",
                label=solver,
            )

        ax.set_xlabel(
            "Tasks per scheduling instance"
        )
        ax.set_ylabel(
            "External SLO miss rate"
        )
        ax.set_title(
            "Capacity-aware scheduling"
        )
        ax.legend(
            fontsize=8
        )
        ax.grid(
            alpha=0.25
        )
        fig.tight_layout()
        fig.savefig(
            out.figures
            / "capacity_scheduling_slo_miss.png",
            dpi=300,
        )
        plt.close(fig)


