# =============================================================================
# Targeted repair of an already completed final run
# =============================================================================

def _clear_directory(path: Path) -> None:
    if path.exists():
        for child in path.iterdir():
            if child.is_dir():
                shutil.rmtree(
                    child
                )
            else:
                child.unlink()
    else:
        path.mkdir(
            parents=True,
            exist_ok=True,
        )


def _latest_subdirectory(path: Path) -> Path | None:
    if not path.exists():
        return None
    dirs = [
        p for p in path.iterdir()
        if p.is_dir()
    ]
    if not dirs:
        return None
    return max(
        dirs,
        key=lambda p: p.stat().st_mtime,
    )


def repair_existing_scheduling_qaoa(
    run_root: Path,
    fast: bool,
) -> None:
    """
    Repair only the two affected components in an existing final result tree:
      * capacity-scheduling instance diversity;
      * Windows QAOA worker execution.

    Prediction, lifecycle target, HCQKL, iQuantum, and their statistics are
    retained because these repairs do not change the trained risk model.
    """
    out = Paths.from_existing(
        run_root
    )

    print(
        "Repairing existing AQUA-SLA run:",
        out.root,
    )

    helpers = write_embedded_helpers(
        out
    )

    helper30 = load_module(
        helpers["compact_qaoa"],
        "aqua_sla_embedded_qaoa_repair",
    )

    helper33 = load_module(
        helpers["circuits"],
        "aqua_sla_embedded_circuit_repair",
    )

    future_path = (
        out.target
        / "future_target_dataset.csv"
    )
    bundle_path = (
        out.models
        / "hcqkl_v2_bundle.joblib"
    )
    risk_path = (
        out.prediction
        / "full_test_risk_scores.csv"
    )

    for p in [
        future_path,
        bundle_path,
        risk_path,
    ]:
        if not p.exists():
            raise FileNotFoundError(
                f"Required existing final artifact missing: {p}"
            )

    # Preserve all replaced outputs.
    stamp = datetime.now().strftime(
        "%Y%m%d_%H%M%S"
    )
    backup = (
        out.root
        / "15_pre_fix_scheduling_qaoa_backup"
        / stamp
    )
    backup.mkdir(
        parents=True,
        exist_ok=True,
    )

    for src in [
        out.scheduling,
        out.qaoa,
        out.statistics,
        out.circuits,
        out.circuit_artifacts,
    ]:
        if src.exists():
            shutil.copytree(
                src,
                backup / src.name,
                dirs_exist_ok=True,
            )

    for name in [
        "qaoa_depth_shots_ablation.csv",
        "qaoa_depth_shots_ablation_summary.csv",
    ]:
        src = (
            out.ablations
            / name
        )
        if src.exists():
            shutil.copy2(
                src,
                backup / name,
            )

    old_final_status = {}
    final_status_path = (
        out.manifest
        / "final_status.json"
    )
    if final_status_path.exists():
        try:
            old_final_status = json.loads(
                final_status_path.read_text(
                    encoding="utf-8"
                )
            )
        except Exception:
            old_final_status = {}

    # Clear only affected result locations.
    for p in [
        out.scheduling,
        out.qaoa,
        out.statistics,
        out.circuits,
        out.circuit_artifacts,
    ]:
        _clear_directory(
            p
        )

    for name in [
        "qaoa_depth_shots_ablation.csv",
        "qaoa_depth_shots_ablation_summary.csv",
    ]:
        p = (
            out.ablations
            / name
        )
        if p.exists():
            p.unlink()

    data = pd.read_csv(
        future_path,
        low_memory=False,
    )
    train, val, test = temporal_split(
        data
    )

    bundle = joblib.load(
        bundle_path
    )

    risk = pd.read_csv(
        risk_path,
        low_memory=False,
    )

    if "_source_row" not in risk.columns:
        raise ValueError(
            "full_test_risk_scores.csv lacks _source_row."
        )

    test_scored = test.merge(
        risk[
            [
                "_source_row",
                "risk_hcqkl",
            ]
        ],
        on="_source_row",
        how="left",
        validate="one_to_one",
    )

    if test_scored[
        "risk_hcqkl"
    ].isna().any():
        missing = int(
            test_scored[
                "risk_hcqkl"
            ].isna().sum()
        )
        raise RuntimeError(
            f"{missing} test rows lack final HCQKL risk scores."
        )

    (
        scheduling_results,
        scheduling_summary,
    ) = run_capacity_scheduling(
        train,
        test_scored,
        out,
        helper30,
        fast,
    )

    scheduling_stats = scheduling_statistics(
        scheduling_results,
        out,
        1000
        if fast
        else BOOTSTRAP_RESAMPLES,
    )

    (
        qaoa_results,
        qaoa_stats,
        qaoa_reliability,
    ) = run_compact_qaoa_fixed(
        train=train,
        test_scored=test_scored,
        out=out,
        helper30=helper30,
        blocks=3
        if fast
        else QAOA_BLOCKS,
        reps=QAOA_REPS,
        shots=128
        if fast
        else QAOA_SHOTS,
        maxiter=10
        if fast
        else QAOA_MAXITER,
        timeout=60
        if fast
        else QAOA_TIMEOUT,
        bootstrap=1000
        if fast
        else BOOTSTRAP_RESAMPLES,
    )

    create_qaoa_compatibility_alias(
        out
    )

    (
        qaoa_ablation,
        qaoa_ablation_summary,
    ) = qaoa_sensitivity(
        train,
        test_scored,
        bundle,
        helper30,
        out,
        fast,
    )

    # Regenerate overall figures from the unchanged prediction evidence and
    # the repaired scheduling results.
    audit_path = (
        out.target
        / "global_vs_task_lifecycle_audit.csv"
    )
    baseline_path = (
        out.prediction
        / "classical_baseline_metrics.csv"
    )
    kernel_path = (
        out.prediction
        / "matched_kernel_test_metrics.csv"
    )
    alpha_path = (
        out.prediction
        / "hcqkl_alpha_sweep.csv"
    )

    make_final_figures(
        pd.read_csv(audit_path),
        pd.read_csv(baseline_path),
        pd.read_csv(kernel_path),
        scheduling_summary,
        pd.read_csv(alpha_path),
        out,
    )

    # Rebuild updated circuit figures from repaired QUBO.
    cmd = [
        sys.executable,
        str(
            helpers["circuits"]
        ),
        "--run-dir",
        str(out.root),
        "--output-dir",
        str(out.circuits),
    ]

    proc = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        check=False,
    )

    (
        out.logs
        / "quantum_circuit_generation_repair.log"
    ).write_text(
        (
            "COMMAND:\n"
            + " ".join(cmd)
            + "\n\nSTDOUT:\n"
            + proc.stdout
            + "\n\nSTDERR:\n"
            + proc.stderr
        ),
        encoding="utf-8",
    )

    if proc.returncode != 0:
        raise RuntimeError(
            "Repaired QAOA circuit figure generation failed."
        )

    circuit_manifest = (
        save_quantum_circuit_artifacts(
            out,
            helper33,
        )
    )

    iq_run = _latest_subdirectory(
        out.iquantum
    )

    write_result_index(
        out,
        iq_run,
    )

    stage_status_path = (
        out.manifest
        / "stage_status.json"
    )
    stage_status = {}

    if stage_status_path.exists():
        try:
            stage_status = json.loads(
                stage_status_path.read_text(
                    encoding="utf-8"
                )
            )
        except Exception:
            stage_status = {}

    stage_status[
        "capacity_scheduling"
    ] = "completed_repaired_heterogeneous_instances"
    stage_status[
        "compact_qaoa"
    ] = "completed_repaired_windows_safe_worker"
    stage_status[
        "quantum_circuit_figures"
    ] = "completed_rebuilt_after_qaoa_repair"
    stage_status[
        "quantum_circuit_artifacts"
    ] = "completed_rebuilt_after_qaoa_repair"

    save_json(
        stage_status,
        stage_status_path,
    )

    repaired_status = dict(
        old_final_status
    )

    repaired_status.update(
        {
            "completed": True,
            "output": str(
                out.root
            ),
            "repair_applied": True,
            "repair_timestamp": datetime.now().isoformat(),
            "repair_backup": str(
                backup
            ),
            "scheduling_instance_selection": (
                "deterministic diversity-stratified selection inside "
                "temporal blocks; repeated task identities removed"
            ),
            "capacity_scheduling_rows": len(
                scheduling_results
            ),
            "capacity_statistics_rows": len(
                scheduling_stats
            ),
            "qaoa_primary_rows": len(
                qaoa_results
            ),
            "qaoa_primary_statistics_rows": len(
                qaoa_stats
            ),
            "qaoa_reliability": qaoa_reliability,
            "qaoa_ablation_rows": len(
                qaoa_ablation
            ),
            "qaoa_ablation_summary_rows": len(
                qaoa_ablation_summary
            ),
            "quantum_circuit_objects_saved": int(
                len(
                    circuit_manifest
                )
            ),
            "stage_status": stage_status,
            "repair_notes": [
                "The Windows QAOA worker now lives in the physical final script instead of a dynamically imported helper module.",
                "Scheduling and QAOA instances are selected by a fixed solver-independent diversity rule inside temporal blocks.",
                "Instance selection uses predicted risk, requested resources, training-derived duration estimates, and scheduling context only.",
                "Realized duration remains evaluation-only; QAOA outcomes are never used for instance selection.",
                "Prediction, HCQKL, lifecycle target, and iQuantum V4 were not rerun because this repair does not change the predictor.",
                "Old affected outputs are preserved under 15_pre_fix_scheduling_qaoa_backup.",
            ],
        }
    )

    save_json(
        repaired_status,
        final_status_path,
    )

    print()
    print(
        "AQUA-SLA SCHEDULING/QAOA REPAIR FINISHED."
    )
    print(
        "Run:",
        out.root,
    )
    print(
        "Backup:",
        backup,
    )
    print(
        json.dumps(
            {
                "qaoa": qaoa_reliability,
                "scheduling_rows": len(
                    scheduling_results
                ),
                "qaoa_ablation_rows": len(
                    qaoa_ablation
                ),
            },
            indent=2,
        )
    )


# =============================================================================
# Main
# =============================================================================

def main() -> None:
    parser = argparse.ArgumentParser(
        description=(
            "Final consolidated AQUA-SLA reviewer-complete experiment suite."
        )
    )

    parser.add_argument(
        "--run-name",
        default="final_reviewer_complete",
    )

    parser.add_argument(
        "--repair-run",
        default=None,
        help=(
            "Repair only scheduling-instance diversity and QAOA execution "
            "inside an already completed final run. Prediction/iQuantum are retained."
        ),
    )

    parser.add_argument(
        "--clean-terminal-events",
        default="FINISH",
    )

    parser.add_argument(
        "--fast",
        action="store_true",
    )

    parser.add_argument(
        "--skip-qaoa",
        action="store_true",
    )

    parser.add_argument(
        "--skip-iquantum",
        action="store_true",
    )

    parser.add_argument(
        "--skip-circuits",
        action="store_true",
    )

    args = parser.parse_args()

    if args.repair_run:
        repair_existing_scheduling_qaoa(
            Path(
                args.repair_run
            ),
            args.fast,
        )
        return

    clean_terminal_events = {
        x.strip().upper()
        for x in args.clean_terminal_events.split(",")
        if x.strip()
    }

    out = Paths.create(
        args.run_name
    )

    print(
        "AQUA-SLA FINAL output:",
        out.root,
    )

    stage_status = {}
    iq_run = None

    helpers = write_embedded_helpers(
        out
    )

    try:
        preflight(
            out,
            skip_iquantum=args.skip_iquantum,
        )
        stage_status["preflight"] = "completed"

        helper30 = load_module(
            helpers["compact_qaoa"],
            "aqua_sla_embedded_qaoa",
        )

        if not PREPARED_DATA.exists():
            raise FileNotFoundError(
                PREPARED_DATA
            )

        raw = pd.read_csv(
            PREPARED_DATA,
            low_memory=False,
        )

        # ------------------------------------------------------------------
        # Target + censoring audit
        # ------------------------------------------------------------------
        prepared = prepare_target_frame(
            raw
        )

        annotated = lifecycle_annotations(
            prepared,
            clean_terminal_events,
        )

        (
            primary,
            target_meta,
            censoring_audit,
        ) = target_audit(
            annotated,
            clean_terminal_events,
            HORIZONS,
            out,
        )

        event_counts = (
            annotated[
                EVENT_COLUMN
            ]
            .value_counts(
                dropna=False
            )
            .rename_axis(
                "event"
            )
            .reset_index(
                name="rows"
            )
        )
        event_counts.to_csv(
            out.target
            / "event_distribution.csv",
            index=False,
        )

        primary.to_csv(
            out.target
            / "future_target_dataset.csv",
            index=False,
        )

        save_json(
            target_meta,
            out.target
            / "future_target_metadata.json",
        )

        train, val, test = temporal_split(
            primary
        )

        split_summary = pd.DataFrame([
            {
                "split": name,
                "rows": len(d),
                "positives": int(
                    d[
                        "future_sla_event"
                    ].sum()
                ),
                "prevalence": float(
                    d[
                        "future_sla_event"
                    ].mean()
                ),
                "time_min": float(
                    d[
                        TIME_COLUMN
                    ].min()
                ),
                "time_max": float(
                    d[
                        TIME_COLUMN
                    ].max()
                ),
            }
            for name, d in [
                ("train", train),
                ("validation", val),
                ("test", test),
            ]
        ])

        split_summary.to_csv(
            out.target
            / "temporal_split_summary.csv",
            index=False,
        )

        stage_status[
            "target_lifecycle_censoring"
        ] = "completed"

        # ------------------------------------------------------------------
        # Prediction + ablations
        # ------------------------------------------------------------------
        horizon_df = horizon_sensitivity(
            annotated,
            clean_terminal_events,
            out,
            args.fast,
        )

        baseline_metrics, _ = (
            run_classical_baselines(
                train,
                val,
                test,
                out,
                args.fast,
            )
        )

        (
            kernel_metrics,
            kernel_subset_pred,
            bundle,
            alpha_df,
        ) = run_matched_kernels(
            train,
            val,
            test,
            out,
            args.fast,
        )

        feature_ablation = (
            feature_group_ablation(
                train,
                val,
                test,
                out,
                args.fast,
            )
        )

        size_ablation = (
            sample_size_ablation(
                train,
                val,
                test,
                out,
                args.fast,
            )
        )

        print(
            "Scoring full untouched temporal test with final HCQKL..."
        )

        full_risk = score_hcqkl_full(
            test,
            bundle,
            chunk_size=128 if args.fast else 256,
        )

        test_scored = test.copy()
        test_scored[
            "risk_hcqkl"
        ] = full_risk

        test_scored[
            [
                "_source_row",
                TIME_COLUMN,
                "future_sla_event",
                "risk_hcqkl",
            ]
        ].to_csv(
            out.prediction
            / "matched_kernel_test_predictions.csv",
            index=False,
        )

        test_scored.to_csv(
            out.prediction
            / "full_test_risk_scores.csv",
            index=False,
        )

        stage_status[
            "prediction_hcqkl"
        ] = "completed"

        # ------------------------------------------------------------------
        # Capacity scheduling
        # ------------------------------------------------------------------
        (
            scheduling_results,
            scheduling_summary,
        ) = run_capacity_scheduling(
            train,
            test_scored,
            out,
            helper30,
            args.fast,
        )

        scheduling_stats = (
            scheduling_statistics(
                scheduling_results,
                out,
                1000
                if args.fast
                else BOOTSTRAP_RESAMPLES,
            )
        )

        stage_status[
            "capacity_scheduling"
        ] = "completed"

        # ------------------------------------------------------------------
        # Compact QAOA
        # ------------------------------------------------------------------
        qaoa_primary = pd.DataFrame()
        qaoa_primary_stats = pd.DataFrame()
        qaoa_reliability = {}

        if not args.skip_qaoa:
            qaoa_primary, qaoa_primary_stats, qaoa_reliability = (
                run_compact_qaoa_fixed(
                    train=train,
                    test_scored=test_scored,
                    out=out,
                    helper30=helper30,
                    blocks=3 if args.fast else QAOA_BLOCKS,
                    reps=QAOA_REPS,
                    shots=128 if args.fast else QAOA_SHOTS,
                    maxiter=10 if args.fast else QAOA_MAXITER,
                    timeout=60 if args.fast else QAOA_TIMEOUT,
                    bootstrap=1000 if args.fast else BOOTSTRAP_RESAMPLES,
                )
            )

            create_qaoa_compatibility_alias(
                out
            )

            qaoa_ablation, qaoa_ablation_summary = (
                qaoa_sensitivity(
                    train,
                    test_scored,
                    bundle,
                    helper30,
                    out,
                    args.fast,
                )
            )

            stage_status[
                "compact_qaoa"
            ] = "completed"
        else:
            stage_status[
                "compact_qaoa"
            ] = "skipped"

        # ------------------------------------------------------------------
        # iQuantum V4 with CORRECTED HCQKL risk pool
        # ------------------------------------------------------------------
        if not args.skip_iquantum:
            helper32 = load_module(
                helpers["iquantum_v4"],
                "aqua_sla_embedded_iquantum_v4",
            )

            # Force all iQuantum results inside this final package.
            helper32.OUTPUT_ROOT = out.iquantum

            iq_args = argparse.Namespace(
                source_run=str(out.root),
                run_name="corrected_hcqkl_calibrated_v4",
                bootstrap=1000 if args.fast else BOOTSTRAP_RESAMPLES,
                slo_quantile=0.90,
                fast=args.fast,
            )

            iq_run = helper32.run_experiment(
                iq_args
            )

            stage_status[
                "iquantum_calibrated_v4"
            ] = "completed"
        else:
            stage_status[
                "iquantum_calibrated_v4"
            ] = "skipped"

        # ------------------------------------------------------------------
        # Updated quantum circuit figures + reusable circuit files
        # ------------------------------------------------------------------
        circuit_manifest = pd.DataFrame()

        if not args.skip_circuits:
            circuit_log = (
                out.logs
                / "quantum_circuit_generation.log"
            )

            cmd = [
                sys.executable,
                str(
                    helpers["circuits"]
                ),
                "--run-dir",
                str(out.root),
                "--output-dir",
                str(out.circuits),
            ]

            proc = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                check=False,
            )

            circuit_log.write_text(
                (
                    "COMMAND:\n"
                    + " ".join(cmd)
                    + "\n\nSTDOUT:\n"
                    + proc.stdout
                    + "\n\nSTDERR:\n"
                    + proc.stderr
                ),
                encoding="utf-8",
            )

            if proc.returncode != 0:
                raise RuntimeError(
                    "Quantum circuit figure generation failed. "
                    f"Inspect {circuit_log}"
                )

            stage_status[
                "quantum_circuit_figures"
            ] = "completed"

            helper33 = load_module(
                helpers["circuits"],
                "aqua_sla_embedded_circuit_artifacts",
            )

            circuit_manifest = (
                save_quantum_circuit_artifacts(
                    out,
                    helper33,
                )
            )

            stage_status[
                "quantum_circuit_artifacts"
            ] = "completed"
        else:
            stage_status[
                "quantum_circuit_figures"
            ] = "skipped"
            stage_status[
                "quantum_circuit_artifacts"
            ] = "skipped"

        # ------------------------------------------------------------------
        # Final figures / reviewer coverage / paper-ready index
        # ------------------------------------------------------------------
        make_final_figures(
            censoring_audit,
            baseline_metrics,
            kernel_metrics,
            scheduling_summary,
            alpha_df,
            out,
        )

        coverage = reviewer_coverage(
            out
        )

        write_result_index(
            out,
            iq_run,
        )

        save_json(
            stage_status,
            out.manifest
            / "stage_status.json",
        )

        final_status = {
            "completed": True,
            "output": str(out.root),
            "source_dataset": str(PREPARED_DATA),
            "source_rows": len(raw),
            "target_eligible_rows": len(primary),
            "target_positives": int(
                primary[
                    "future_sla_event"
                ].sum()
            ),
            "target_prevalence": float(
                primary[
                    "future_sla_event"
                ].mean()
            ),
            "selected_alpha_rbf": float(
                bundle["best_alpha"]
            ),
            "selected_alpha_quantum": float(
                1.0
                - bundle["best_alpha"]
            ),
            "classical_models": (
                baseline_metrics[
                    "model"
                ].tolist()
            ),
            "kernel_models": (
                kernel_metrics[
                    "model"
                ].tolist()
            ),
            "capacity_scheduling_rows": len(
                scheduling_results
            ),
            "capacity_statistics_rows": len(
                scheduling_stats
            ),
            "qaoa_primary_rows": len(
                qaoa_primary
            ),
            "qaoa_primary_statistics_rows": len(
                qaoa_primary_stats
            ),
            "qaoa_reliability": qaoa_reliability,
            "iquantum_output": (
                str(iq_run)
                if iq_run
                else None
            ),
            "reviewer_concerns_mapped": len(
                coverage
            ),
            "quantum_circuit_figures_saved": (
                len(list(out.circuits.glob("*.png")))
                + len(list(out.circuits.glob("*.jpeg")))
            ),
            "quantum_circuit_objects_saved": int(
                len(circuit_manifest)
            ),
            "quantum_circuit_qpy_collection": (
                str(
                    out.circuit_artifacts
                    / "all_quantum_circuits.qpy"
                )
                if (
                    out.circuit_artifacts
                    / "all_quantum_circuits.qpy"
                ).exists()
                else None
            ),
            "stage_status": stage_status,
            "claim_boundaries": [
                "The disruption target is project-defined and is not a Google contractual SLA field.",
                "HCQKL alpha is selected by blocked temporal validation; a boundary alpha is retained if selected.",
                "External SLO outcomes are evaluated after scheduling and are absent from the assignment objective.",
                "Raw and repaired QAOA are reported separately.",
                "Qiskit quantum-kernel/QAOA results are simulator based.",
                "iQuantum is discrete-event simulation rather than physical quantum hardware.",
                "No quantum computational advantage is claimed unless supported by measured evidence.",
            ],
        }

        save_json(
            final_status,
            out.manifest
            / "final_status.json",
        )

        save_json(
            {
                "project": "AQUA-SLA",
                "version": "final-reviewer-complete-qaoa-windows-fix-v2",
                "created": datetime.now().isoformat(),
                "python": sys.version,
                "platform": platform.platform(),
                "output": str(out.root),
                "fast": args.fast,
                "primary_horizon_seconds": PRIMARY_HORIZON,
                "clean_terminal_events": sorted(
                    clean_terminal_events
                ),
                "early_features": EARLY_FEATURES,
                "disruptive_events": sorted(
                    DISRUPTIVE_EVENTS
                ),
                "alpha_grid": ALPHA_GRID,
                "scheduling_batch_sizes": (
                    [4]
                    if args.fast
                    else SCHED_BATCH_SIZES
                ),
                "scheduling_blocks": (
                    5
                    if args.fast
                    else SCHED_BLOCKS
                ),
                "qaoa_blocks": (
                    3
                    if args.fast
                    else QAOA_BLOCKS
                ),
                "bootstrap_resamples": (
                    1000
                    if args.fast
                    else BOOTSTRAP_RESAMPLES
                ),
                "quantum_circuit_outputs": {
                    "rendered_figures_directory": str(
                        out.circuits
                    ),
                    "reusable_circuit_directory": str(
                        out.circuit_artifacts
                    ),
                    "formats": [
                        "QPY",
                        "text diagram",
                        "OpenQASM 2 when fully bound and exportable",
                        "OpenQASM 3 when exportable",
                    ],
                },
            },
            out.manifest
            / "run_manifest.json",
        )

        print()
        print(
            "AQUA-SLA FINAL REVIEWER-COMPLETE RUN FINISHED."
        )
        print(
            "Output:",
            out.root,
        )
        print(
            json.dumps(
                final_status,
                indent=2,
            )
        )

    except Exception as exc:
        stage_status[
            "fatal_error"
        ] = repr(exc)

        save_json(
            stage_status,
            out.manifest
            / "stage_status.json",
        )

        save_json(
            {
                "completed": False,
                "output": str(out.root),
                "error": repr(exc),
                "stage_status": stage_status,
                "note": (
                    "Completed stage outputs are checkpointed and retained."
                ),
            },
            out.manifest
            / "final_status.json",
        )

        raise


if __name__ == "__main__":
    main()
